INSERT INTO products(name, region, category, price, stock, summary, description, spec, qualification, status, farmer, user_id, created_at, updated_at) VALUES
('龙泉驿水蜜桃', '四川', '水果', 49.90, 85, '皮薄汁多，香甜可口', '产自成都龙泉驿核心产区，果实饱满圆润，果肉细腻多汁。', '2.5kg/箱', '农产品地理标志', 'published', '蜀乡果园', 3, NOW(), NOW()),
('普洱茶饼', '云南', '茶饮', 128.00, 36, '古树晒红，陈香醇厚', '采自云南西双版纳古茶山，2018年春料压制，汤色红浓透亮，入口甘甜回韵。', '357g/饼', '有机茶认证', 'published', '滇茗茶庄', 3, NOW(), NOW()),
('宁夏枸杞', '宁夏', '粮油', 38.00, 200, '特级大果，免洗即食', '产自宁夏中宁核心产区，颗颗精选，粒大肉厚，可直接食用或泡茶炖汤。', '500g/袋', '绿色食品认证', 'published', '塞上田园', 3, NOW(), NOW()),
('黑龙江非转基因大豆', '黑龙江', '粮油', 15.00, 300, '颗粒饱满，蛋白含量高', '黑土地种植，传统品种，非转基因认证，适合制豆腐豆浆等豆制品。', '2.5kg/袋', '非转基因认证', 'published', '黑土地农场', 3, NOW(), NOW()),
('烟台红富士苹果', '山东', '水果', 32.00, 150, '脆甜多汁，色泽红润', '山东烟台核心产区直供，果型端正，甜度可达15度以上，清脆爽口。', '4kg/箱', '无公害农产品认证', 'published', '胶东果园', 3, NOW(), NOW()),
('云南野生菌菇礼盒', '云南', '蔬菜', 88.00, 45, '松茸羊肚菌组合装', '精选云南高海拔野生松茸、羊肚菌、牛肝菌，干制密封，煲汤炖鸡鲜美无比。', '200g/盒', '野生菌检验检疫证书', 'published', '云岭山珍', 3, NOW(), NOW()),
('舟山带鱼', '浙江', '水产', 56.00, 60, '东海新鲜捕捞', '舟山渔场新鲜捕捞带鱼，肉质细嫩鲜美，冷冻锁鲜，顺丰冷链配送。', '1kg/袋', '检验检疫合格', 'published', '东海渔家', 3, NOW(), NOW()),
('散养土鸡蛋', '湖北', '肉禽蛋', 45.00, 120, '山林散养，蛋黄红亮', '大别山区山林散养土鸡，饲喂玉米谷物，蛋黄饱满红亮，蛋清浓稠。', '30枚/箱', '无公害农产品认证', 'published', '大别山农家', 3, NOW(), NOW()),
('安岳柠檬', '四川', '水果', 19.90, 180, '新鲜采摘，维C丰富', '四川安岳中国柠檬之乡直供，果皮金黄，汁多酸爽，泡水调饮首选。', '2.5kg/箱', '农产品地理标志', 'published', '蜀乡果园', 3, NOW(), NOW()),
('内蒙古风干牛肉', '内蒙古', '肉禽蛋', 79.00, 90, '草原散养，传统风干', '内蒙古科尔沁草原散养黄牛后腿肉，传统工艺风干，肉质紧实有嚼劲。', '250g/袋', '清真食品认证', 'published', '草原牧歌', 3, NOW(), NOW());
INSERT INTO news(title, author, category, summary, content, status, user_id, published_at, created_at, updated_at) VALUES
('2026年中央一号文件惠农政策解读', '平台农讯组', '政策解读', '聚焦粮食安全与农民增收新举措', '2026年中央一号文件继续聚焦三农，明确提出强化粮食安全保障、促进农民持续增收、推进乡村建设等重点工作。在粮食安全方面，文件要求稳定粮食播种面积，提高单产水平，推进高标准农田建设。在农民增收方面，文件提出发展农产品加工业，拓宽农民就业渠道，完善联农带农机制。各地农业农村部门正在抓紧制定实施细则，确保政策落地见效。', 'published', 3, NOW(), NOW(), NOW()),
('现代农业产业园建设指南发布', '平台农讯组', '政策解读', '农业农村部公布最新创建标准', '农业农村部近日发布了《现代农业产业园建设指南（2026年版）》，明确了产业园创建的七大核心指标。文件要求，到2028年在全国建设500个国家级现代农业产业园，重点支持粮食、油料、蔬菜、水果等主导产业。每个产业园需具备规模化种养基地、农产品加工物流区和科技支撑体系，带动周边农户参与产业发展。', 'published', 3, NOW(), NOW(), NOW()),
('水稻绿色防控技术要点', '农技推广站', '种植技术', '从育苗到收获全程减药增效方案', '水稻绿色防控技术核心在于预防为主、综合防治。一是选用抗病品种，从源头减少病害发生；二是推广秧田期覆盖防虫网，阻隔稻飞虱等传毒昆虫；三是田间设置性诱捕器和杀虫灯，诱杀二化螟、稻纵卷叶螟等害虫；四是合理施用生物农药如苏云金杆菌、井冈霉素等替代化学农药。通过综合运用，可实现减药30%—50%。', 'published', 3, NOW(), NOW(), NOW()),
('设施蔬菜冬季保温关键技术', '农技推广站', '种植技术', '大棚多层覆盖与补光技巧详解', '冬季设施蔬菜保温是确保产量和品质的关键。推荐采用三层覆盖技术，即外层棚膜加中层保温被加内层小拱棚，可提高棚内温度5—8°C。补光方面，使用LED植物补光灯每日补充光照4—6小时，促进光合作用。同时注意合理通风排湿，预防灰霉病、霜霉病等低温高湿病害。地膜覆盖配合滴灌，可有效提高地温。', 'published', 3, NOW(), NOW(), NOW()),
('果园水肥一体化实操手册', '农技推广站', '种植技术', '滴灌系统搭建与施肥方案设计', '水肥一体化技术是果树高效种植的核心。系统搭建包括首部枢纽（水泵、过滤器、施肥器）、输配水管网和灌水器三部分。施肥方案应根据果树不同生育期调整，萌芽期以氮肥为主，花期增施磷钾肥，果实膨大期补充钙镁中量元素。推荐使用水溶性肥料，浓度控制在0.1%—0.3%，每次滴灌时间30—60分钟。', 'published', 3, NOW(), NOW(), NOW()),
('有机农产品认证流程简化通知', '平台农讯组', '政策解读', '认证周期压缩至30个工作日', '国家认证认可监督管理委员会日前印发通知，将进一步简化有机农产品认证流程。一是将认证周期从原来的45个工作日压缩至30个工作日；二是对已获得绿色食品认证的产品，免于现场检查重复环节；三是推动各省建立有机认证一站式服务窗口。此次改革预计将惠及超10万家农业生产经营主体。', 'published', 3, NOW(), NOW(), NOW()),
('全国农产品电商交易额突破新高', '运营中心', '产业动态', '前三季度农产品网销增长35%', '商务部最新数据显示，2026年前三季度全国农产品网络零售额突破8000亿元，同比增长35%。其中生鲜电商增长最为迅猛，增速达52%，社区团购和直播带货成为主要增量渠道。从品类看，水果、茶叶、粮油稳居前三，预制菜、有机食品等新兴品类增速超60%。中西部地区农产品上行明显提速。', 'published', 3, NOW(), NOW(), NOW()),
('预制菜产业带动农产品加工升级', '运营中心', '产业动态', '各地加快布局中央厨房项目', '预制菜产业正成为农产品加工业升级的重要引擎。据行业协会统计，目前全国已有超过20个省份出台了预制菜产业扶持政策，各地累计规划建设中央厨房项目超过300个。预制菜的发展有效拉动了蔬菜、畜禽、水产等原料需求，推动上游种植养殖标准化、规模化生产。农业农村部预计，到2028年预制菜市场规模将突破万亿元。', 'published', 3, NOW(), NOW(), NOW()),
('本周主要农产品批发价格监测', '运营中心', '市场行情', '猪肉稳中略降，蔬菜季节性上涨', '本周全国农产品批发价格200指数为126.8，环比上涨0.3%。猪肉批发均价每公斤22.5元，环比微降0.9%；牛肉81.3元/公斤，环比持平；鸡蛋10.2元/公斤，环比上涨1.5%。蔬菜价格受降温影响上涨明显，黄瓜、西红柿、菠菜涨幅居前，分别上涨8.2%、5.6%和4.8%。水果价格总体平稳。', 'published', 3, NOW(), NOW(), NOW()),
('秋粮收购价格走势分析', '运营中心', '市场行情', '玉米大豆价格同比均有提升', '截至12月中旬，全国秋粮收购进度已完成85%，累计收购量超过1.2亿吨。价格方面，玉米市场均价每斤1.18元，同比上涨6.3%，受饲料需求增加和深加工开工率提升双重拉动。大豆收购价每斤2.65元，同比上涨4.7%，国储收购托市效果明显。预计春节前粮食价格将维持稳中偏强走势，建议农户合理安排售粮节奏。', 'published', 3, NOW(), NOW(), NOW());
